"""Querying and adjusting the privileges held by the current process."""

from .errors import WTokenError
from . import _winapi


def _ensure_windows():
    """Raise WTokenError if not on Windows."""
    if not _winapi.is_windows():
        raise WTokenError(
            "token privilege operations require Windows",
            kind="unsupported",
        )


def _luid_to_int(luid):
    """Convert a LUID struct to an integer for comparison/hashing."""
    return (luid.HighPart << 32) | luid.LowPart


def _int_to_luid(value):
    """Convert an integer back to a LUID struct."""
    luid = _winapi.LUID()
    luid.LowPart = value & 0xFFFFFFFF
    luid.HighPart = (value >> 32) & 0xFFFFFFFF
    return luid


def _open_token_query():
    """Open the current process token with TOKEN_QUERY access."""
    try:
        return _winapi.open_process_token(_winapi.TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("failed to open process token: %s" % exc, kind="os") from exc


def _open_token_adjust():
    """Open the current process token with TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY."""
    try:
        return _winapi.open_process_token(
            _winapi.TOKEN_ADJUST_PRIVILEGES | _winapi.TOKEN_QUERY
        )
    except OSError as exc:
        raise WTokenError("failed to open process token: %s" % exc, kind="os") from exc


def _get_privilege_list():
    """Return list of (name, enabled) for every privilege in the token."""
    _ensure_windows()
    handle = _open_token_query()
    try:
        privs = _winapi.get_token_privileges(handle)
    except OSError as exc:
        raise WTokenError("failed to query token privileges: %s" % exc, kind="os") from exc
    finally:
        _winapi.close_handle(handle)

    result = []
    for luid, attrs in privs:
        try:
            name = _winapi.lookup_privilege_name(luid)
        except OSError:
            # Unknown privilege LUID - skip or use numeric representation
            # This shouldn't normally happen but be safe
            continue
        enabled = bool(attrs & _winapi.SE_PRIVILEGE_ENABLED)
        result.append((name, enabled))
    return result


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    Each key is a privilege name and each value indicates whether that
    privilege is **currently enabled** in the token.  Privileges that are
    held but disabled appear with a value of ``False``.
    """
    return dict(_get_privilege_list())


def has_privilege(name):
    """Return ``True`` when the token holds ``name``, regardless of state.

    A privilege can be held but currently disabled; this function returns
    ``True`` in that case because the token *does* carry the privilege.
    """
    if not isinstance(name, str) or not name:
        return False
    _ensure_windows()
    # Try to look up the LUID for this name - if it fails, it's not a valid
    # privilege name at all, so the token can't hold it.
    try:
        _winapi.lookup_privilege_value(name)
    except OSError:
        return False

    handle = _open_token_query()
    try:
        privs = _winapi.get_token_privileges(handle)
    except OSError as exc:
        raise WTokenError("failed to query token privileges: %s" % exc, kind="os") from exc
    finally:
        _winapi.close_handle(handle)

    target_luid = _winapi.lookup_privilege_value(name)
    target_key = _luid_to_int(target_luid)
    for luid, _attrs in privs:
        if _luid_to_int(luid) == target_key:
            return True
    return False


def set_privilege(name, enabled=True):
    """Enable or disable a held privilege.

    Raises :class:`WTokenError` with ``kind="badarg"`` when the privilege
    name is unknown or empty, and with ``kind="os"`` when the system call
    fails (including when the token does not actually hold the privilege).
    """
    _ensure_windows()

    if not isinstance(name, str) or not name:
        raise WTokenError(
            "privilege name must be a non-empty string",
            kind="badarg",
            privilege=name,
        )

    # Validate the privilege name exists on this system
    try:
        luid = _winapi.lookup_privilege_value(name)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        ) from exc

    # Check that the token actually holds this privilege before trying to adjust
    handle_check = _open_token_query()
    try:
        privs = _winapi.get_token_privileges(handle_check)
    except OSError as exc:
        raise WTokenError("failed to query token privileges: %s" % exc, kind="os") from exc
    finally:
        _winapi.close_handle(handle_check)

    target_key = _luid_to_int(luid)
    held = any(_luid_to_int(l) == target_key for l, _a in privs)
    if not held:
        raise WTokenError(
            "the token does not hold privilege %r" % (name,),
            kind="badarg",
            privilege=name,
        )

    # Now adjust the privilege
    handle = _open_token_adjust()
    try:
        _winapi.adjust_token_privileges(handle, luid, enabled)
    except OSError as exc:
        err_code = exc.args[0] if exc.args else 0
        if err_code == 1300:  # ERROR_NOT_ALL_ASSIGNED
            raise WTokenError(
                "cannot adjust privilege %r: not held by token" % (name,),
                kind="badarg",
                privilege=name,
            ) from exc
        raise WTokenError(
            "failed to adjust privilege %r: %s" % (name, exc),
            kind="os",
            privilege=name,
        ) from exc
    finally:
        _winapi.close_handle(handle)


def privilege_luid(name):
    """Return the system LUID for a privilege name as an integer.

    The returned value matches what the kernel uses internally and can be
    passed to :func:`privilege_name` to recover the original name.
    """
    _ensure_windows()

    if not isinstance(name, str) or not name:
        raise WTokenError(
            "privilege name must be a non-empty string",
            kind="badarg",
            privilege=name,
        )

    try:
        luid = _winapi.lookup_privilege_value(name)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        ) from exc

    return _luid_to_int(luid)


def privilege_name(luid):
    """Return the privilege name for a system LUID.

    Accepts an integer as returned by :func:`privilege_luid`.
    """
    _ensure_windows()

    try:
        value = int(luid)
    except (TypeError, ValueError):
        raise WTokenError(
            "a privilege identifier must be an integer, got %r" % (luid,),
            kind="badarg",
        )

    luid_struct = _int_to_luid(value)
    try:
        return _winapi.lookup_privilege_name(luid_struct)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege identifier: %r" % (luid,),
            kind="badarg",
        ) from exc

