from .errors import WTokenError
from . import _winapi


_ELEVATION_TYPE_NAMES = {
    1: "default",
    2: "full",
    3: "limited",
}

_INTEGRITY_LEVEL_NAMES = {
    0x0000: "untrusted",
    0x1000: "low",
    0x2000: "medium",
    0x2100: "medium-plus",
    0x3000: "high",
    0x4000: "system",
    0x5000: "protected-process",
}


def elevation():
    """Return ``{"elevated": bool, "type": str}`` for the current token.

    On non-Windows platforms this raises :class:`WTokenError` with
    ``kind="unsupported"``.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "elevation queries require Windows",
            kind="unsupported",
        )

    try:
        handle = _winapi.open_process_token(_winapi.TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("failed to open process token: %s" % exc, kind="os") from exc

    try:
        is_elevated = _winapi.get_token_elevation(handle)
        elev_type = _winapi.get_token_elevation_type(handle)
    except OSError as exc:
        raise WTokenError("failed to query token elevation: %s" % exc, kind="os") from exc
    finally:
        _winapi.close_handle(handle)

    type_name = _ELEVATION_TYPE_NAMES.get(elev_type, "unknown")
    return {"elevated": is_elevated, "type": type_name}


def integrity_level():
    """Return the mandatory integrity level name of the current token.

    Returns a human-readable string such as ``"medium"``, ``"high"``, or
    ``"system"``.  On non-Windows platforms this raises :class:`WTokenError`
    with ``kind="unsupported"``.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "integrity level queries require Windows",
            kind="unsupported",
        )

    try:
        handle = _winapi.open_process_token(_winapi.TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("failed to open process token: %s" % exc, kind="os") from exc

    try:
        rid = _winapi.get_token_integrity_level(handle)
    except OSError as exc:
        raise WTokenError("failed to query integrity level: %s" % exc, kind="os") from exc
    finally:
        _winapi.close_handle(handle)

    # Look up by exact match first, then try to find the closest lower bound
    name = _INTEGRITY_LEVEL_NAMES.get(rid)
    if name is not None:
        return name

    # Find the highest known level that is <= rid
    best = None
    for level_rid, level_name in sorted(_INTEGRITY_LEVEL_NAMES.items()):
        if level_rid <= rid:
            best = level_name
        else:
            break
    return best if best is not None else "unknown"

